using System;
using System.IO;
using Microsoft.Win32;
using System.Runtime.InteropServices;

namespace FPSLimiter
{
    /// <summary>
    /// Bundled Oswald Medium (SIL Open Font License 1.1, see OFL-Oswald.txt), embedded as base64 so no loose
    /// file is needed. Installed per-user (no administrator rights needed) next to the RTSS overlay preset.
    /// </summary>
    internal static class OswaldFont
    {
        /// <summary>GDI face name RTSS and the overlay preset use.</summary>
        public const string FaceName = "Oswald Medium";
        public const string Weight = "500";

        private const string FileName = "Oswald-Medium.ttf";
        private const string RegistryValueName = "Oswald Medium (TrueType)";
        private const string FontsRegistryKey = @"Software\Microsoft\Windows NT\CurrentVersion\Fonts";

        public static byte[] GetBytes()
        {
            return Convert.FromBase64String(Base64);
        }

        /// <summary>True when a font called "Oswald Medium" is registered for this user or for the machine.</summary>
        public static bool IsInstalled()
        {
            try
            {
                return HasFont(Registry.CurrentUser) || HasFont(Registry.LocalMachine);
            }
            catch
            {
                return false;
            }
        }

        private static bool HasFont(RegistryKey hive)
        {
            using (var key = hive.OpenSubKey(FontsRegistryKey))
            {
                if (key == null) return false;
                foreach (var name in key.GetValueNames())
                {
                    if (!name.StartsWith(FaceName, StringComparison.OrdinalIgnoreCase)) continue;
                    var value = key.GetValue(name) as string;
                    if (string.IsNullOrWhiteSpace(value)) continue;
                    // Per-user entries hold a full path; machine entries are usually a bare file name in C:\Windows\Fonts.
                    var path = Path.IsPathRooted(value)
                        ? value
                        : Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), value);
                    if (File.Exists(path)) return true;
                }
            }
            return false;
        }

        /// <summary>
        /// Installs Oswald Medium for the current user (%LOCALAPPDATA%\Microsoft\Windows\Fonts) and tells running
        /// programs about it. Does nothing if it is already installed. Throws on failure.
        /// </summary>
        public static void Install()
        {
            if (IsInstalled()) return;

            var dir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "Microsoft", "Windows", "Fonts");
            Directory.CreateDirectory(dir);
            var path = Path.Combine(dir, FileName);
            if (!File.Exists(path)) File.WriteAllBytes(path, GetBytes());

            using (var key = Registry.CurrentUser.CreateSubKey(FontsRegistryKey))
            {
                key.SetValue(RegistryValueName, path, RegistryValueKind.String);
            }

            try
            {
                AddFontResource(path);
                UIntPtr ignored;
                SendMessageTimeout((IntPtr)0xFFFF, 0x001D /* WM_FONTCHANGE */, UIntPtr.Zero, IntPtr.Zero, 0x0002 /* SMTO_ABORTIFHUNG */, 1000, out ignored);
            }
            catch
            {
                // The font is registered; it just becomes visible to running programs after the next sign-in.
            }
        }

        [DllImport("gdi32.dll", CharSet = CharSet.Unicode)]
        private static extern int AddFontResource(string lpFileName);

        [DllImport("user32.dll", CharSet = CharSet.Auto)]
        private static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint msg, UIntPtr wParam, IntPtr lParam, uint flags, uint timeout, out UIntPtr result);

